using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithPromptsFromAssembly()
    .WithResourcesFromAssembly();

var app = builder.Build();

app.MapMcp();                      // Exposes MCP endpoint at /mcp (Streamable HTTP)
app.MapGet("/health", () => "ok"); // Health check for container orchestrators

app.Run();

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Retrieve a specific configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = AppConfiguration.Current;
        return config.TryGetValue(key, out var value)
            ? value
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("List all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join("\n", AppConfiguration.Current.Keys);
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json")]
    [Description("Full application configuration as JSON")]
    public static string GetAllSettings()
    {
        return JsonSerializer.Serialize(AppConfiguration.Current,
            new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/environment", Name = "Environment Info",
        MimeType = "application/json")]
    [Description("Current runtime environment information")]
    public static string GetEnvironment()
    {
        var info = new
        {
            MachineName = Environment.MachineName,
            OsVersion = Environment.OSVersion.ToString(),
            DotNetVersion = Environment.Version.ToString(),
            ProcessId = Environment.ProcessId
        };
        return JsonSerializer.Serialize(info, new JsonSerializerOptions { WriteIndented = true });
    }
}

/// <summary>Sample configuration store used by tools and resources.</summary>
public static class AppConfiguration
{
    public static Dictionary<string, string> Current { get; } = new()
    {
        ["app:name"] = "HttpMcpServer",
        ["app:version"] = "1.0.0",
        ["app:environment"] = "Development",
        ["feature:caching"] = "true",
        ["feature:rate-limiting"] = "false"
    };
}

